SELECT 
FROM app_info
WHERE deleted = 0

    AND app_name LIKE CONCAT('%', #{appName}, '%')


    AND version = #{version}


    AND build_number = #{buildNumber}


    AND is_beta = #{isBeta}

ORDER BY create_time DESC

