app_name = #{appName}, package_name = #{packageName}, version = #{version}, build_number = #{buildNumber}, features = #{features}, is_beta = #{isBeta}, path = #{path}, download_times = #{downloadTimes}, size = #{size}, deleted = #{deleted}, show_update_popup = #{showUpdatePopup}, force_update = #{forceUpdate}
